CREATE TABLE festivals (
    id         UUID  PRIMARY KEY DEFAULT uuid_generate_v4(),
    festival   TEXT  NOT NULL,
    date       BIGINT NOT NULL,
    created_at BIGINT NOT NULL DEFAULT (EXTRACT(EPOCH FROM NOW()))::BIGINT,
    CONSTRAINT uniq_festival_date UNIQUE (festival, date)
);
CREATE INDEX idx_festivals_date ON festivals (date);

CREATE TABLE panchanga (
    id               UUID   PRIMARY KEY DEFAULT uuid_generate_v4(),
    date             BIGINT NOT NULL UNIQUE,
    samvatsara       TEXT   NOT NULL DEFAULT '',
    ayana            TEXT   NOT NULL DEFAULT '',
    rutu             TEXT   NOT NULL DEFAULT '',
    masa             TEXT   NOT NULL DEFAULT '',
    paksha           TEXT   NOT NULL DEFAULT '',
    tithi            TEXT   NOT NULL DEFAULT '',
    nakshatra        TEXT   NOT NULL DEFAULT '',
    yoga             TEXT   NOT NULL DEFAULT '',
    karana           TEXT   NOT NULL DEFAULT '',
    vasara           TEXT   NOT NULL DEFAULT '',
    shraddha_tithi   TEXT   NOT NULL DEFAULT '',
    masa_niyamaka    TEXT   NOT NULL DEFAULT '',
    festivals_events TEXT   NOT NULL DEFAULT '',
    sunrise          TEXT   NOT NULL DEFAULT '',
    sunset           TEXT   NOT NULL DEFAULT '',
    rahukala         TEXT   NOT NULL DEFAULT '',
    gulikala         TEXT   NOT NULL DEFAULT '',
    yamaganda        TEXT   NOT NULL DEFAULT '',
    created_at       BIGINT NOT NULL DEFAULT (EXTRACT(EPOCH FROM NOW()))::BIGINT
);
CREATE INDEX idx_panchanga_date ON panchanga (date);


